// Arma el contexto que lee el agente. Si no hay reunión, tiene:false.
const filas = $input.all();
let reunion = { tiene: false, fecha_hora_texto: null, titulo: null };

const r = filas[0] && filas[0].json ? filas[0].json : null;
if (r && r.fecha_hora) {
  let txt = r.fecha_hora;
  try {
    txt = new Date(r.fecha_hora).toLocaleString('es-AR', {
      timeZone: 'America/Argentina/Buenos_Aires', dateStyle: 'full', timeStyle: 'short'
    });
  } catch (e) {}
  reunion = { tiene: true, fecha_hora_texto: txt, titulo: r.evento || null };
}
return [{ json: { reunion_cliente: reunion } }];
